using System.Text;using System.Text.Json;namespace QuantForge.Core;public sealed class AndroidResearchLaunchPreviewFileStore{private readonly string _path;public AndroidResearchLaunchPreviewFileStore(string path){if(string.IsNullOrWhiteSpace(path))throw new ArgumentException("A preview path is required.",nameof(path));_path=Path.GetFullPath(path);}public void Save(AndroidResearchLaunchPreview value){ArgumentNullException.ThrowIfNull(value);if(value.CanSubmitOrders)throw new InvalidOperationException("Launch preview cannot grant order authority.");Directory.CreateDirectory(Path.GetDirectoryName(_path)!);File.WriteAllText(_path,JsonSerializer.Serialize(value,new JsonSerializerOptions{WriteIndented=true}),new UTF8Encoding(false));}public AndroidResearchLaunchPreview Load(){var value=JsonSerializer.Deserialize<AndroidResearchLaunchPreview>(File.ReadAllText(_path))??throw new InvalidOperationException("Android launch preview JSON is invalid.");if(value.CanSubmitOrders)throw new InvalidOperationException("Persisted launch preview grants order authority.");return value;}}
